          "swfi_url": "https://www.swfi.com/v1/compass/69b8df136f17e3e60d10e8eb",
          "summary": "LINK : https://www3.calpers.ca.gov/a/about/doing-business-with-calpers/bid-opportunities The California Public Employees’ Retirement System (CalPERS) Investment Office is seeking proposals from qualified firms to establish a Spring-Fed Pool of investment consultants operating under a fiduciary standard of care. The purpose of this Request for Proposal (RFP) is to create a pool of service providers that can be engaged on an as-needed basis to support various project-based and ad hoc initiatives. Selected consultants will provide portfolio due diligence and advisory support across multiple Investment Office program areas, including various asset classes and internal support teams. All services must adhere to a fiduciary standard of care, ensuring that consultants act in the best interest of CalPERS. This opportunity is offered under a continuous filing process, allowing qualified firms to submit proposals on an ongoing basis."
