          "attachment_url": "",
          "source_url": "https://www.swfi.com/v1/compass/68a49ce3f2fa8e4bcd67cc7f",
          "swfi_url": "https://www.swfi.com/v1/compass/68a49ce3f2fa8e4bcd67cc7f",
          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_03.pdf The job performance contents focus on direct management of overseas stocks, including derivatives, the composition and management of investable stocks for active funds, and the establishment of overseas stock portfolios. The role involves selecting and managing overseas stock management companies, forming strategic partnerships with overseas investment managers, and overseeing supplementary fund management through consignment or direct management. It also includes performance analysis, long-term overseas stock strategy development, and conducting detailed industry and company research. Additional responsibilities include handling matters related to overseas stock research, direct management, and consignment oversight. The competency units encompass corporate analysis, stock investment strategy development, portfolio composition, and the establishment of stock investment goals. These competencies ensure that the NPS effectively manages its overseas stock exposure in line with its global investment strategy. Required Skills & Knowledge Candidates must have solid knowledge of National Pension Fund-related regulations, capital markets, capital market laws, and financial investment business practices. Additional expertise is required in foreign exchange and derivatives, corporate and industry analysis, economic indicators, and transaction structures across financial markets. Essential skills include financial analysis, English communication (conversation, reading, writing), office and spreadsheet program utilization, application of statistical software, company/industry analysis, setting risk limits, and interpreting and applying relevant laws. Career Requirements Applicants must have at least three years of experience as a full-time investment manager and a minimum of one month of relevant job experience in overseas stock or related portfolio management. Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM, CAIA, Tax Accountant, Investment Asset Management Specialist, Financial Investment Analyst, and Asset Manager. These qualifications provide strong credentials for managing the complexities of international equity markets."
