          "swfi_url": "https://www.swfi.com/v1/compass/68a49e29ad471be467aef331",
          "summary": "LINK : https://dym-upload.saramin.co.kr/upload/dym2_5/332/3590/filedown/2025-08-04/03_nps_250804_04.pdf The job performance contents focus on direct management of overseas bonds, including derivatives, as well as the selection and management of securities firms handling these bonds. Responsibilities include developing overseas bond strategies, sector allocation, and managing derivatives and foreign exchange exposures for hedging purposes. The role also entails selecting and overseeing overseas bond management companies, proposing and managing foreign exchange and derivative products, and handling interbank transactions. Additional responsibilities include supporting back-office operations in foreign exchange and derivatives, conducting research, and managing other matters related to overseas bond investment and risk. The competency units include overseas bond management, corporate analysis, bond investment strategy development, portfolio composition, and establishing bond investment goals. These competencies ensure the effective integration of overseas fixed income within the NPS’s overall asset allocation framework. Required Skills & Knowledge Candidates must possess strong knowledge of National Pension Fund-related regulations, capital markets, financial investment laws, and financial mathematics. Familiarity with foreign exchange and derivatives concepts, corporate and economic indicators, and transaction structures across financial markets is critical. Essential skills include financial analysis, English communication (conversation, reading, and writing), office and spreadsheet program utilization, statistical software application, setting risk limits, and interpreting and applying relevant laws. Career Requirements Applicants must have at least three years of full-time investment manager experience and a minimum of one month of relevant job experience in bond or derivatives management. Preferred Qualifications Preferred certifications include CFA (Level 1–3), CPA (Korea/USA/Other countries), Attorney (Korea/USA/Other countries), Actuary, Certified International Investment Analyst (CIIA), FRM, CAIA, Tax Accountant, Investment Asset Management Specialist, Financial Investment Analyst, and Asset Manager. These qualifications demonstrate advanced expertise in managing global fixed income and derivatives markets. Due Date is Estimated."
