          "summary": "Abu Dhabi Investment Authority (ADIA) seeks to allocate to more private equity funds for 2025. The focus is on areas with less of a U.S. tariff impact, or areas of opportunity. Target region: North America, Japan, Australia Earlier, a wholly owned subsidiary of the ADIA is set to invest up to US$ 1.5 billion in GLP Pte Ltd, a business investor, manager, and builder. GLP will use the capital for its growth strategy. GLP and ADIA have an established working relationship, and this investment is widely seen as an endorsement of GLP’s execution capabilities and track record. GLP’s financial position will clearly be enhanced by ADIA’s initial capital deployment of US$ 500 million, which is expected to accelerate the group’s mission of creating differentiated, scaled platforms across logistics, digital infrastructure and renewable energy. It is believed that these sectors will benefit from e-commerce and AI and cloud technologies. Mohamed Al Qubaisi, Executive Director of the Real Estate Department at ADIA, commented: “We have successfully invested in GLP funds for a number of years. This transaction will allow us to deepen that relationship, support the company in its next phase of growth and scale our exposure to new economy sectors, in line with our strategy.”"
