          "summary": "Sacramento County Employees Retirement System (SCERS) has set aside $520m for 2026—$300m for real estate and $220m for infrastructure. The real estate plan includes commitments to up to two core funds ($65m each) and three non-core/value-add funds ($50m each), with a focus on niche property types and US core portfolio rebalancing. In 2025 so far, SCERS has committed $50m to FPA Core Plus Fund VI and $30m to FPA Apartment Opportunity Fund IX, with another $50m non-core commitment expected by year-end, against a $270m target. SCERS remains underallocated to real estate (6% vs. 8% target). For infrastructure, it plans 4–6 commitments of ~$55m each in 2026, prioritising regulated and social infrastructure assets."
