          "excerpt": "The Qatar Investment Authority (QIA) agreed to buy ​Derby, United Kingdom-based Doncasters Group shares at the IPO price, according to an SEC ​filing. QIA is investing $75 million aerospace precision parts maker ​Doncasters Group ahead of its U.S. ‌listing. At the midpoint of the ​IPO price range, QIA would receive about ⁠2.5 million ordinary shares…",
          "content": "The Qatar Investment Authority (QIA) agreed to buy ​Derby, United Kingdom-based Doncasters Group shares at the IPO price, according to an SEC ​filing. QIA is investing $75 million aerospace precision parts maker ​Doncasters Group ahead of its U.S. ‌listing. At the midpoint of the ​IPO price range, QIA would receive about ⁠2.5 million ordinary shares through the private ​placement, the filing showed. Doncasters is seeking up to $746.7 million in the IPO by offering 23.3 million shares priced between $28 and $32 apiece."
